public:
    int maximumSafenessFactor(vector<vector<int>>& grid) {
        int n = grid.size();
        if (grid[0][0] == 1 || grid[n - 1][n - 1] == 1) return 0;
        vector<vector<int>> dist(n, vector<int>(n, -1));
        queue<pair<int, int>> q;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    dist[r][c] = 0;
                    q.push({r, c});
                }
            }
        }
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (auto& d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.push({nr, nc});
                }
            }
        }
        int low = 0, high = min(dist[0][0], dist[n - 1][n - 1]), ans = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            vector<vector<bool>> vis(n, vector<bool>(n, false));
            vis[0][0] = true;
            queue<pair<int, int>> bq;
            bq.push({0, 0});
            bool reachable = false;
            while (!bq.empty()) {
                auto [r, c] = bq.front(); bq.pop();
                if (r == n - 1 && c == n - 1) {
                    reachable = true;
                    break;
                }
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && !vis[nr][nc] && dist[nr][nc] >= mid) {
                        vis[nr][nc] = true;
                        bq.push({nr, nc});
                    }
                }
            }
            if (reachable) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maximumSafenessFactor(List<List<Integer>> grid) {
        int n = grid.size();
        if (grid.get(0).get(0) == 1 || grid.get(n - 1).get(n - 1) == 1) return 0;
        int[][] dist = new int[n][n];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid.get(r).get(c) == 1) {
                    dist[r][c] = 0;
                    q.add(new int[]{r, c});
                }
            }
        }
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int r = cell[0], c = cell[1];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        int low = 0, high = Math.min(dist[0][0], dist[n - 1][n - 1]), ans = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            boolean[][] vis = new boolean[n][n];
            vis[0][0] = true;
            Queue<int[]> bq = new LinkedList<>();
            bq.add(new int[]{0, 0});
            boolean reachable = false;
            while (!bq.isEmpty()) {
                int[] cell = bq.poll();
                int r = cell[0], c = cell[1];
                if (r == n - 1 && c == n - 1) {
                    reachable = true;
                    break;
                }
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n && !vis[nr][nc] && dist[nr][nc] >= mid) {
                        vis[nr][nc] = true;
                        bq.add(new int[]{nr, nc});
                    }
                }
            }
            if (reachable) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

