var maximumSafenessFactor = function(grid) {
    const n = grid.length;
    if (grid[0][0] === 1 || grid[n - 1][n - 1] === 1) return 0;
    const dist = Array.from({ length: n }, () => new Array(n).fill(-1));
    const q = [];
    let head = 0;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                dist[r][c] = 0;
                q.push([r, c]);
            }
        }
    }
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (head < q.length) {
        const [r, c] = q[head++];
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && dist[nr][nc] === -1) {
                dist[nr][nc] = dist[r][c] + 1;
                q.push([nr, nc]);
            }
        }
    }
    let low = 0, high = Math.min(dist[0][0], dist[n - 1][n - 1]), ans = 0;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        const vis = Array.from({ length: n }, () => new Array(n).fill(false));
        vis[0][0] = true;
        const bq = [[0, 0]];
        let bHead = 0;
        let reachable = false;
        while (bHead < bq.length) {
            const [r, c] = bq[bHead++];
            if (r === n - 1 && c === n - 1) {
                reachable = true;
                break;
            }
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !vis[nr][nc] && dist[nr][nc] >= mid) {
                    vis[nr][nc] = true;
                    bq.push([nr, nc]);
                }
            }
        }
        if (reachable) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
